func separateParenGroups(parenString string) []string {
	cnt := 0
	group := ""
	results := make([]string, 0)

	for _, ch := range parenString {
		if ch == '(' {
			cnt++
		}
		if ch == ')' {
			cnt--
		}
		if ch != ' ' {
			group += string(ch)
		}
		if cnt == 0 {
			if group != "" {
				results = append(results, group)
			}
			group = ""
		}
	}

	return results
}

