import "testing"

func TestSeparateParenGroups(t *testing.T) {
	candidate := separate_paren_groups

	if got := candidate("(()()) ((())) () ((())()())"); !equalStringSlices(got, []string{"(()())", "((()))", "()", "((())()())"}) {
		t.Fatalf("unexpected result: got %#v", got)
	}
	if got := candidate("() (()) ((())) (((())))"); !equalStringSlices(got, []string{"()", "(())", "((()))", "(((())))"}) {
		t.Fatalf("unexpected result: got %#v", got)
	}
	if got := candidate("(()(())((())))"); !equalStringSlices(got, []string{"(()(())((())))"}) {
		t.Fatalf("unexpected result: got %#v", got)
	}
	if got := candidate("( ) (( )) (( )( ))"); !equalStringSlices(got, []string{"()", "(())", "(()())"}) {
		t.Fatalf("unexpected result: got %#v", got)
	}
}

func equalStringSlices(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

