import "testing"

func TestNextSmallestPalindrome(t *testing.T) {
	if got := next_smallest_palindrome(99); got != 101 {
		t.Fatalf("next_smallest_palindrome(99) = %d, want %d", got, 101)
	}
	if got := next_smallest_palindrome(1221); got != 1331 {
		t.Fatalf("next_smallest_palindrome(1221) = %d, want %d", got, 1331)
	}
	if got := next_smallest_palindrome(120); got != 121 {
		t.Fatalf("next_smallest_palindrome(120) = %d, want %d", got, 121)
	}
}

