import "strings"

func snakeToCamel(word string) string {
	parts := strings.Split(word, "_")
	var b strings.Builder
	for _, p := range parts {
		if p == "" {
			b.WriteByte('_')
			continue
		}
		b.WriteString(strings.ToUpper(p[:1]) + p[1:])
	}
	return b.String()
}

