	if got := snake_to_camel("python_language"); got != "PythonLanguage" {
		t.Fatalf("snake_to_camel(%q) = %q, want %q", "python_language", got, "PythonLanguage")
	}
	if got := snake_to_camel("programming_language"); got != "ProgrammingLanguage" {
		t.Fatalf("snake_to_camel(%q) = %q, want %q", "programming_language", got, "ProgrammingLanguage")
