import "math"

func hasCloseElements(numbers []float64, threshold float64) bool {
	for idx, elem := range numbers {
		for idx2, elem2 := range numbers {
			if idx != idx2 {
				distance := math.Abs(elem - elem2)
				if distance < threshold {
					return true
				}
			}
		}
	}
	return false
}

