import "strings"

func separateParenGroups(parenString string) []string {
	var result []string
	current := make([]rune, 0, len(parenString))
	currentDepth := 0

	for _, c := range parenString {
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			continue
		}
		switch c {
		case '(':
			currentDepth++
			current = append(current, c)
		case ')':
			currentDepth--
			current = append(current, c)
			if currentDepth == 0 {
				result = append(result, string(current))
				current = current[:0]
			}
		default:
			// Ignore any other characters (not expected per problem statement).
		}
	}

	_ = strings.Builder{} // keep imports idiomatic if needed elsewhere
	return result
}

